const o=/^(?=.*[0-9])(?=.*[a-zA-Z]).{8,}$/,E=/^1[3-9]\d{9}$/,u=/^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$/,s=/^[A-Za-z0-9]{3,30}$/;function a(n="请输入3-30位字母或数字的账号"){return(e,t,r)=>{if(!t||!t.trim())return r(new Error("账号不能为空"));if(!s.test(t.trim()))return r(new Error(n));r()}}function f(n="密码至少8位，须同时包含数字和字母"){return(e,t,r)=>{if(!t)return r(new Error("密码不能为空"));if(!o.test(t))return r(new Error(n));r()}}function d(n=!1){return(e,t,r)=>{if(!t)return n?r(new Error("手机号不能为空")):r();if(!E.test(String(t).trim()))return r(new Error("请输入11位正确的手机号"));r()}}function l(n=!1){return(e,t,r)=>{if(!t)return n?r(new Error("邮箱不能为空")):r();const i=String(t).trim();if(i.length>100)return r(new Error("邮箱长度不能超过100"));if(!u.test(i))return r(new Error("请输入正确的邮箱格式"));r()}}export{a,f as b,l as c,d};
